import{_ as i,l as r,o as e,c as s,v as l,p as n,x as t,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"掩模显影与清洗","description":"","frontmatter":{"title":"掩模显影与清洗","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/mask-develop-clean.md","filePath":"litho/mask-develop-clean.md","lastUpdated":1789023840000}'),h={name:"litho/mask-develop-clean.md"};function c(B,a,m,A,_,u){const o=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=l('<h1 id="掩模显影与清洗" tabindex="-1">掩模显影与清洗 <a class="header-anchor" href="#掩模显影与清洗" aria-label="Permalink to &quot;掩模显影与清洗&quot;">​</a></h1><div class="epigraph"><p>写束只把潜像放进胶；显影决定胶边，清洗决定哪些离子留下。雾化的种子往往在这一步，而不在扫描机。</p><footer>—— 对照电子束胶显影、掩模湿洗与硫酸根残留的产线讨论</footer></div><p><a href="/litho/mask-etch-sidewall">上一课</a>把吸收体边钉成带倾角的墙。缺口是墙前后的湿法：e-beam 胶显影、去胶、SPM/SC1 一类清洗。本课钉显影与清洗。图形缺陷怎么被看见，留给[下一课](/litho/mask-inspection-d2d-d2db）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>掩模胶（化学放大或非化学放大 e-beam 胶）的显影对照晶圆轨道，但基板是 6 寸方、膜是铬或吸收体，设备与化学不同。显影残胶会变成刻蚀后的亮/暗缺陷；过显影吃 CD。清洗要去颗粒与金属离子，却不能毁 pellicle 区、不能把硫酸根/铵根留到曝光后结晶——那是后课 <a href="/litho/mask-haze">掩模雾化</a> 的种子。</p><p>缺口是<strong>湿法残差</strong>，不是再讲 RIE 角。把缺陷全写成写入器脏，会漏掉显影槽与清洗台。</p><h3 id="清洗越狠-雾化风险不一定越低" tabindex="-1">清洗越狠，雾化风险不一定越低 <a class="header-anchor" href="#清洗越狠-雾化风险不一定越低" aria-label="Permalink to &quot;清洗越狠，雾化风险不一定越低&quot;">​</a></h3><p>历史 SPM（硫酸双氧水）去有机很强，硫酸根残留加氨环境可在曝光下长铵盐晶体。改化学、加强漂洗、控制存储气氛，是雾化课的工艺源头，本课先钉：清洗规格含离子残留，不只含颗粒计数。</p><p><span class="marginnote">EUV 无传统有机 pellicle 时，清洗与搬运颗粒直接打到多层；有 pellicle 时，安装前的最后一次清洗仍决定膜下洁净。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流程：后烘（若需要）→ 显影 → 硬烘 → 刻蚀 → 去胶 → 多步清洗 → 检验。CD 采样在显影后与刻蚀后都做，才能把胶偏置与刻蚀偏置拆开给 MPC。干燥方式（旋干、IPA）影响塌陷与水印，对照晶圆 <a href="/litho/pattern-collapse">pattern collapse</a>，但掩模胶厚与附着力不同，不能直接抄晶圆表面活性剂表。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>化学放大胶的酸在 PEB 后决定溶解速率；e-beam 短程散射已经糊了潜像，显影阈值切在糊过的能量上——所以 PEC 与显影是一对。清洗的静电与 pH 决定颗粒再吸附；金属离子在石英与 MoSi 表面的吸附等温线决定雾化前体浓度。曝光（尤其 DUV 高剂量）提供能量让残留物种迁移、成核。</p>',13)),(e(),n(E,null,{default:t(()=>[p(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20LAT%5B%22e-beam%20%E6%BD%9C%E5%83%8F%22%5D%20--%3E%20DEV%5B%22%E6%98%BE%E5%BD%B1%3A%20%E8%83%B6%E8%BE%B9%22%5D%0A%20%20DEV%20--%3E%20ETCH%5B%22%E5%88%BB%E8%9A%80%22%5D%0A%20%20ETCH%20--%3E%20CLN%5B%22%E5%8E%BB%E8%83%B6%20%2B%20%E6%B9%BF%E6%B4%97%22%5D%0A%20%20CLN%20--%3E%20ION%5B%22%E7%A6%BB%E5%AD%90%20%2F%20%E9%A2%97%E7%B2%92%E6%AE%8B%E7%95%99%22%5D%0A%20%20ION%20--%3E%20HAZE%5B%22%E5%90%8E%E8%AF%BE%3A%20%E9%9B%BE%E5%8C%96%22%5D%0A%20%20ION%20--%3E%20INSP%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E6%A3%80%E9%AA%8C%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写具体药液浓度。不把晶圆 TMAH 显影课重讲一遍。清洗不修复空白多层缺陷。</p><p>后课默认：版在湿法后带着某一洁净与离子状态；下一课用光学比较来抓图形缺陷。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>显影定胶边，清洗定颗粒与离子；二者都进缺陷与 CD。</li><li>离子残留是雾化前体，颗粒计数不是清洗的唯一 KPI。</li><li>ADI/AEI 成对测量才能拆 MPC。</li><li>出处：掩模 e-beam 胶显影与湿洗产线讨论；雾化与硫酸根残留的公开文献传统。</li></ul>',5))])}const P=i(h,[["render",c]]);export{D as __pageData,P as default};
